/*
 * A371443  Numbers whose binary indices are nonprime numbers.
 * https://oeis.org/A371443
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 15, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation: a(n) is the n-th positive integer whose binary
 * representation contains 1‑bits only at nonprime positions.  The
 * sequence is generated by searching the integers in increasing order
 * and caching the results.  For n up to about 10 000 the algorithm
 * runs well under the time limit. */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>

/* Choose a prime test limit large enough for all bit positions that
 * may appear in the numbers of interest (≈20–30 bits for n ≤ 10 000). */
#define PRIME_LIMIT 2048

/* Prime flags for positions 0…PRIME_LIMIT. */
static bool prime_pos[PRIME_LIMIT + 1];
static bool primes_init = false;

/* Prime sieve for the position indices. */
static void init_prime_positions(void)
{
    if (primes_init) return;
    for (idx_t i = 0; i <= PRIME_LIMIT; ++i) prime_pos[i] = true;
    prime_pos[0] = prime_pos[1] = false;
    for (idx_t i = 2; i * i <= PRIME_LIMIT; ++i)
        if (prime_pos[i])
            for (idx_t j = i * i; j <= PRIME_LIMIT; j += i)
                prime_pos[j] = false;
    primes_init = true;
}

/* Test whether integer x has a 1‑bit at a prime position. */
static bool has_prime_bit(idx_t x)
{
    idx_t pos = 1;
    while (x)
    {
        if (x & 1ULL)
        {
            if (pos <= PRIME_LIMIT)
            {
                if (prime_pos[pos]) return true;
            }
            else
            {
                /* For safety handle larger positions (unlikely). */
                for (idx_t d = 2; d * d <= pos; ++d)
                    if (pos % d == 0) return false;
                return true;
            }
        }
        x >>= 1;
        ++pos;
    }
    return false;
}

/* Cache for computed terms. */
static seq_t *cache = NULL;
static idx_t cache_size = 0;
static idx_t cache_cap   = 0;

/* Ensure the cache contains at least n terms. */
static void ensure_cache(idx_t n)
{
    if (cache_size >= n) return;

    if (cache_cap == 0)
    {
        cache_cap = 64;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }
    else if (cache_cap < n)
    {
        while (cache_cap < n) cache_cap *= 2;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }

    idx_t next_val = (cache_size == 0) ? 1 : ((idx_t)cache[cache_size - 1] + 1);
    for (idx_t i = cache_size; i < n; ++i)
    {
        while (has_prime_bit(next_val))
            ++next_val;
        cache[i] = (seq_t)next_val;
        ++next_val;
    }
    cache_size = n;
}

/* External linkage function required by the build system. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset is 1, so n≥1 in practice */
    init_prime_positions();        /* first-time initialization */
    ensure_cache(n);
    return cache[n - 1];
}
